library(data.table);library(hdf5r);source('upr_robustness/modules/scoring_helpers.R')
f<-H5File$new('independent_validation/HepG2_complete.h5ad','r')
sy<-as.character(annotation(f,'var','gene_name'));genes<-as.character(annotation(f,'obs','gene'));gg<-as.character(annotation(f,'obs','gem_group'));u<-fread('reconstruction/cross_dataset/phase2_upr_rpe1/phase2_gene_universe.tsv')[[1]];spec<-readRDS('reconstruction/cross_dataset/phase2_upr_rpe1/phase2_axis_spec.rds');s<-fread('reconstruction/cross_dataset/phase2_upr_rpe1/source_rank_inputs.tsv');rk<-fread('reconstruction/cross_dataset/phase2_upr_rpe1/all_source_comparator_rankings.tsv')[method=='UPR_priority'][order(rank)]
print(data.table(universe=length(u),measured=sum(u%in%sy),UPR=length(spec$UPR$positive),UPR_measured=sum(spec$UPR$positive%in%sy)));print(setdiff(spec$UPR$positive,sy));print(head(sort(table(genes),decreasing=T)));print(table(gg));
cnt<-as.data.table(table(genes));setnames(cnt,c('gene','cells'));print(merge(rk[1:20,.(gene,rank)],cnt,all.x=T));fwrite(data.table(symbol=sy),'independent_validation/feature_metadata.tsv',sep='\t');fwrite(cnt,'independent_validation/target_counts_metadata.tsv',sep='\t');saveRDS(list(symbol=sy,gene=genes,gem=gg,UMI=as.numeric(annotation(f,'obs','UMI_count'))),'independent_validation/cell_metadata.rds');f$close_all()
